begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','edit_flight',array['uuid','timestamp with time zone','text','text','timestamp with time zone','text','text','integer','text'],'Owner edit RPC exists');
insert into auth.users(id,email) select ('19700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'edit-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.memberships(user_id,role) select ('19700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,4) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('19700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Edit pilot','KPAO','licensed' from generate_series(1,4) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('19710000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19700000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',2,case when n=2 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,4) n;
insert into public.flight_recipients(flight_id,user_id) values('19710000-0000-4000-8000-000000000002','19700000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) select ('19720000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('19710000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19700000-0000-4000-8000-000000000002' from generate_series(1,2) n;
update public.flight_requests set status='accepted' where flight_id='19710000-0000-4000-8000-000000000001';
create temporary table edit_original as select * from public.flights where id='19710000-0000-4000-8000-000000000001';
create temporary table edit_history as select to_jsonb(r) as row from public.flight_requests r;
grant select on edit_original to authenticated;
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('19700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.edit(f integer default 1,overrides jsonb default '{}') returns jsonb language plpgsql as $$
declare v jsonb;begin
 select to_jsonb(r) into v from edit_original r;
 v:=v||overrides;
 return public.edit_flight(('19710000-0000-4000-8000-'||lpad(f::text,12,'0'))::uuid,(v->>'updated_at')::timestamptz,v->>'departure_airport',v->>'destination_airport',(v->>'departure_at')::timestamptz,v->>'departure_timezone',v->>'aircraft_description',(v->>'pilot_places')::integer,v->>'notes');
end;$$;
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.edit_flight(uuid,timestamptz,text,text,timestamptz,text,text,integer,text)'::regprocedure),'Definer edit has fixed search path');
select ok(has_function_privilege('authenticated','public.edit_flight(uuid,timestamptz,text,text,timestamptz,text,text,integer,text)','EXECUTE'),'Authenticated edit granted');
select ok(not has_function_privilege('anon','public.edit_flight(uuid,timestamptz,text,text,timestamptz,text,text,integer,text)','EXECUTE'),'Anonymous edit revoked');
select ok(not has_function_privilege('service_role','public.edit_flight(uuid,timestamptz,text,text,timestamptz,text,text,integer,text)','EXECUTE'),'Service role edit revoked');
set local role anon;
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Anonymous edit denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Missing actor denied');
select pg_temp.actor(5);
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Missing member cannot spoof admin');
select pg_temp.actor(4);
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Unrelated admin cannot edit');
select pg_temp.actor(2);
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Accepted requester cannot edit');
select pg_temp.actor(1);
select throws_ok($$select pg_temp.edit(99)$$,'42501',null,'Missing flight shares owner denial');
select throws_ok($$update public.flights set notes='bypass'$$,'42501',null,'Direct member edits remain closed');
select is(pg_temp.edit()->>'code','already_updated','Matching no-op does not rewrite timestamps');
select is(pg_temp.edit(1,'{"departure_airport":"KSFO"}'),'{"code":"repost_required"}'::jsonb,'Departure airport change after acceptance requires repost');
select is(pg_temp.edit(1,'{"destination_airport":"KSJC"}'),'{"code":"repost_required"}'::jsonb,'Destination change after acceptance requires repost');
select is(pg_temp.edit(1,jsonb_build_object('departure_at',now()+interval '3 days')),'{"code":"repost_required"}'::jsonb,'Instant change after acceptance requires repost');
select is(pg_temp.edit(1,'{"departure_timezone":"America/Los_Angeles"}'),'{"code":"repost_required"}'::jsonb,'Timezone change after acceptance requires repost');
select is(pg_temp.edit(1,'{"aircraft_description":"PA28"}'),'{"code":"repost_required"}'::jsonb,'Aircraft change after acceptance requires repost');
reset role;
select is((select to_jsonb(f) from public.flights f where id='19710000-0000-4000-8000-000000000001'),(select to_jsonb(f) from edit_original f),'No-op and rejected material edits preserve complete original flight');
set local role authenticated;
select is(pg_temp.edit(1,'{"pilot_places":1,"notes":"Updated briefing"}')->>'code','updated','Notes/capacity may change down to accepted count');
reset role;
create temporary table edit_winner as select to_jsonb(f) as row from public.flights f where id='19710000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.edit(1,'{"pilot_places":1,"notes":"Updated briefing"}')->>'code','already_updated','Lost-response retry safely confirms same content with stale original token');
select is(pg_temp.edit(1,'{"notes":"Different stale edit"}'),'{"code":"flight_conflict"}'::jsonb,'Different stale edit cannot overwrite winner');
reset role;
select is((select to_jsonb(f) from public.flights f where id='19710000-0000-4000-8000-000000000001'),(select row from edit_winner),'Matching retry and stale conflict preserve entire winner flight');
select results_eq($$select id,owner_id,created_at,visibility,status from public.flights where id='19710000-0000-4000-8000-000000000001'$$,$$select id,owner_id,created_at,visibility,status from edit_original$$,'Edits preserve identity, ownership, creation, privacy and status');
select ok((select f.updated_at>o.updated_at from public.flights f join edit_original o using(id)),'Edit revision advances even within one transaction');
select results_eq($$select to_jsonb(r) from public.flight_requests r order by id$$,$$select row from edit_history order by row->>'id'$$,'Allowed/blocked edits never rewrite accepted or pending requests');
select throws_ok($$update public.flights set departure_airport='KSFO' where id='19710000-0000-4000-8000-000000000001'$$,'23514',null,'Persistence guard blocks privileged material bypass');
insert into public.flight_requests(flight_id,requester_id) values('19710000-0000-4000-8000-000000000001','19700000-0000-4000-8000-000000000003');
update public.flights set pilot_places=2 where id='19710000-0000-4000-8000-000000000001';
update public.flight_requests set status='accepted' where requester_id='19700000-0000-4000-8000-000000000003';
delete from edit_original;insert into edit_original select * from public.flights where id='19710000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.edit(1,'{"pilot_places":1}'),'{"code":"capacity_conflict"}'::jsonb,'Cannot reduce below accepted count');
reset role;
select throws_ok($$update public.flights set pilot_places=1 where id='19710000-0000-4000-8000-000000000001'$$,'23514',null,'Persistence guard blocks capacity bypass');
delete from edit_original;insert into edit_original select * from public.flights where id='19710000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.edit(2,'{"departure_airport":"KSFO","destination_airport":"KSJC","aircraft_description":"PA28","departure_timezone":"America/Los_Angeles"}')->>'code','updated','Material changes allowed with pending requests only');
reset role;
select is((select departure_local_date from public.flights where id='19710000-0000-4000-8000-000000000002'),(select (departure_at at time zone departure_timezone)::date from public.flights where id='19710000-0000-4000-8000-000000000002'),'Edit derives local departure date');
select is((select count(*)::integer from public.flight_recipients),1,'Edit retains private selections');
select is((select status::text from public.flight_requests where flight_id='19710000-0000-4000-8000-000000000002'),'pending','Material edit does not manufacture participant approval');
delete from edit_original;insert into edit_original select * from public.flights where id='19710000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select pg_temp.edit(2,'{"updated_at":null}')$$,'22023',null,'Revision required');
select throws_ok($$select pg_temp.edit(2,'{"departure_at":"infinity"}')$$,'22023',null,'Nonfinite departure rejected');
select throws_ok($$select pg_temp.edit(2,'{"departure_at":"2000-01-01T00:00Z"}')$$,'22023',null,'Past proposed departure rejected');
select throws_ok($$select pg_temp.edit(2,'{"departure_airport":"bad"}')$$,'22023',null,'Airport validation remains enforced');
select throws_ok($$select pg_temp.edit(2,'{"pilot_places":0}')$$,'22023',null,'Capacity must remain positive');
select throws_ok($$select pg_temp.edit(2,'{"departure_timezone":"PST"}')$$,'22023',null,'Named timezone required');
select throws_ok($$select pg_temp.edit(2,jsonb_build_object('notes',repeat('n',2001)))$$,'22023',null,'Notes stay bounded');
reset role;
update public.flights set status='cancelled' where id='19710000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.edit(2,'{"notes":"Late edit"}'),'{"code":"flight_unavailable"}'::jsonb,'Cancelled flight cannot be edited');
reset role;
update public.flights set departure_at=now()-interval '1 day' where id='19710000-0000-4000-8000-000000000003';
set local role authenticated;
select is(pg_temp.edit(3,'{"notes":"Past edit"}'),'{"code":"flight_unavailable"}'::jsonb,'Past flight cannot be edited');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned fixture' where user_id='19700000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Disabled actual owner denied');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='19700000-0000-4000-8000-000000000001';
delete from public.profiles where user_id='19700000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.edit()$$,'42501',null,'Incomplete owner cannot edit flight plan');
reset role;
select * from finish();
rollback;
